#include <cstdint>

class Register
{
public:
    std::uint64_t get64() const { return m_value; }
    std::uint32_t get32() const { return static_cast<std::uint32_t>(m_value); }
    std::uint16_t get16() const { return static_cast<std::uint16_t>(m_value); }
    std::uint8_t get8() const { return static_cast<std::uint8_t>(m_value); }

    void set64(std::uint64_t v) { m_value = v; }
    void set32(std::uint64_t v) { m_value = v & 0xFFFFFFFFull; }                                   // upper half cleared
    void set16(std::uint64_t v) { m_value = (m_value & ~0xFFFFull) | (v & 0xFFFFull); }           // the rest kept
    void set8(std::uint64_t v) { m_value = (m_value & ~0xFFull) | (v & 0xFFull); }

private:
    std::uint64_t m_value{ 0 };
};

unitTests:
TEST("the example")
{
    Register r;
    r.set64(0xFFFFFFFFFFFFFFFFull);
    r.set8(7);
    CHECK_EQ(r.get64(), 0xFFFFFFFFFFFFFF07ull);
    r.set16(300);
    CHECK_EQ(r.get64(), 0xFFFFFFFFFFFF012Cull);
    r.set32(5);
    CHECK_EQ(r.get64(), 5ull);
}
TEST("reading parts") { Register r; r.set64(0x1122334455667788ull); CHECK_EQ(r.get32(), 0x55667788u); CHECK_EQ(static_cast<unsigned>(r.get16()), 0x7788u); CHECK_EQ(static_cast<unsigned>(r.get8()), 0x88u); }
TEST("extra high bits are dropped") { Register r; r.set8(0x1FF); CHECK_EQ(r.get64(), 0xFFull); r.set16(0xABCDEF); CHECK_EQ(r.get64(), 0xCDEFull); }
TEST("set32 of minus one") { Register r; r.set32(0xFFFFFFFFu); CHECK_EQ(r.get64(), 0x00000000FFFFFFFFull); }
TEST("set16 keeps the upper bits") { Register r; r.set64(0xAAAAAAAAAAAAAAAAull); r.set16(0); CHECK_EQ(r.get64(), 0xAAAAAAAAAAAA0000ull); }

